create policy saved_job_read on public.jobs for select to authenticated using (exists(select 1 from public.applications a where a.job_id=jobs.id and a.user_id=(select auth.uid())));
create table public.application_approvals (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, cv_document_id uuid references public.application_documents(id) on delete set null, cover_document_id uuid references public.application_documents(id) on delete set null, approved_at timestamptz not null default now());
create index application_approvals_app_idx on public.application_approvals(application_id,approved_at desc);
create table public.manual_submissions (id uuid primary key default gen_random_uuid(), application_id uuid not null unique references public.applications(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, approval_id uuid not null references public.application_approvals(id), evidence text not null check(length(trim(evidence)) between 3 and 1000), recorded_at timestamptz not null default now());
alter table public.application_approvals enable row level security; alter table public.manual_submissions enable row level security;
create policy approval_read on public.application_approvals for select to authenticated using(user_id=(select auth.uid()));
create policy manual_submission_read on public.manual_submissions for select to authenticated using(user_id=(select auth.uid()));
grant select on public.application_approvals,public.manual_submissions to authenticated;
create function public.guard_application_submission() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then if new.status<>'saved' then raise exception 'New applications must start saved'; end if; elsif new.status='applied' and old.status<>'applied' and not exists(select 1 from public.manual_submissions s where s.application_id=new.id and s.user_id=new.user_id) then raise exception 'Manual submission confirmation required'; end if; return new; end $$;
create trigger application_submission_guard before insert or update of status on public.applications for each row execute function public.guard_application_submission();
create function public.approve_application(p_id uuid,p_cv uuid,p_cover uuid) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; begin if uid is null then return 'not_found'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if a.status not in ('saved','preparing','review_required','action_required') or exists(select 1 from public.manual_submissions where application_id=p_id) then return 'invalid_state'; end if; if p_cv is not null and not exists(select 1 from public.application_documents where id=p_cv and application_id=p_id and user_id=uid and kind='cv') then return 'invalid_document'; end if; if p_cover is not null and not exists(select 1 from public.application_documents where id=p_cover and application_id=p_id and user_id=uid and kind='cover_letter') then return 'invalid_document'; end if; insert into public.application_approvals(application_id,user_id,cv_document_id,cover_document_id) values(p_id,uid,p_cv,p_cover); update public.applications set status='action_required',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'Preparation approved for manual handoff'); return 'approved'; end $$;
create function public.record_manual_application(p_id uuid,p_approval uuid,p_evidence text) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; begin if uid is null then return 'not_found'; end if; if p_evidence is null or length(trim(p_evidence)) not between 3 and 1000 then return 'invalid_evidence'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if exists(select 1 from public.manual_submissions where application_id=p_id) then return 'already_recorded'; end if; if a.status<>'action_required' or not exists(select 1 from public.application_approvals where id=p_approval and application_id=p_id and user_id=uid) then return 'invalid_state'; end if; insert into public.manual_submissions(application_id,user_id,approval_id,evidence) values(p_id,uid,p_approval,trim(p_evidence)); update public.applications set status='applied',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'External submission self-reported by user'); return 'recorded'; end $$;
revoke all on function public.approve_application(uuid,uuid,uuid) from public; revoke all on function public.record_manual_application(uuid,uuid,text) from public;
grant execute on function public.approve_application(uuid,uuid,uuid) to authenticated; grant execute on function public.record_manual_application(uuid,uuid,text) to authenticated;
